d=open('untitled-encore.exe','rb').read()
TEXT_RAW=0x400; TEXT_VA=0x140001000; TEXT_SZ=0xc307
code=d[TEXT_RAW:TEXT_RAW+TEXT_SZ]
md=capstone.Cs(capstone.CS_ARCH_X86, capstone.CS_MODE_64)
md.detail=True
lines=list(md.disasm(code, TEXT_VA))

def fmt(ins):
    s=f'{ins.address:#x}: {ins.mnemonic} {ins.op_str}'
    if 'rip' in ins.op_str:
        tgt = ins.address + ins.size
        # find disp
        for op in ins.operands:
            if op.type==capstone.x86.X86_OP_MEM and op.mem.base==capstone.x86.X86_REG_RIP:
                s += f'   ; ={tgt+op.mem.disp:#x}'
    return s

mode=sys.argv[1]
if mode=='ref':
    want=int(sys.argv[2],16)
    for ins in lines:
        f=fmt(ins)
        if f'={want:#x}' in f:
            print(f)
elif mode=='range':
    lo=int(sys.argv[2],16); hi=int(sys.argv[3],16)
    for ins in lines:
        if lo<=ins.address<hi:
            print(fmt(ins))
elif mode=='allrefs':
    lo=int(sys.argv[2],16); hi=int(sys.argv[3],16)
    for ins in lines:
        f=fmt(ins)
        if ';' in f:
            t=int(f.split('=')[-1],16)
            if lo<=t<hi:
                print(f)
